using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Reflection;using System.Diagnostics;using UnityEditor;using UnityEngine;using MashBoxSDK.AnimationStudio;using Object=UnityEngine.Object;
public static class StudioMoveViewportPerformance {
 static readonly BindingFlags F=BindingFlags.Instance|BindingFlags.Static|BindingFlags.NonPublic;
 static AnimationStudioWindow controller;static MashBoxStudioViewport view;static StudioModelEditor editor;static long previous;static bool capturing;static int sample;static double deadline;static Action<Mesh> normals;static Action<bool> changed;static Dictionary<string,List<double>> times=new Dictionary<string,List<double>>();static StringBuilder report=new StringBuilder();
 static void Add(string name,double ms){if(!times.TryGetValue(name,out var list))times[name]=list=new List<double>();list.Add(ms);}
 static void BeforeGui(SceneView candidate){if(candidate==view){int id=GUIUtility.GetControlID(0x4d535450,FocusType.Passive);GUIUtility.hotControl=id;}}
 public static void Run(){EditorApplication.delayCall+=Begin;}
 static void Begin(){try{var model=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/FrameProbe.fbx");var doc=StudioModelDocument.Import(model,"Assets/MovePerformanceFrame.asset");controller=ScriptableObject.CreateInstance<AnimationStudioWindow>();typeof(AnimationStudioWindow).GetField("modelingMode",F).SetValue(controller,true);typeof(AnimationStudioWindow).GetField("modelDocument",F).SetValue(controller,doc);typeof(AnimationStudioWindow).GetMethod("OpenViewport",F).Invoke(controller,null);view=Resources.FindObjectsOfTypeAll<MashBoxStudioViewport>().Single(v=>v.Studio==controller);view.position=new Rect(0,0,1500,950);SceneView.beforeSceneGui+=BeforeGui;editor=(StudioModelEditor)typeof(AnimationStudioWindow).GetField("modelEditor",F).GetValue(controller);doc=editor.Document;int active=doc.nodes.FindIndex(n=>n.name=="Body"&&n.mesh);editor.SelectObject(active);var points=editor.ActiveMesh.vertices;typeof(StudioModelEditor).GetField("mode",F).SetValue(editor,StudioModelEditor.ComponentMode.Vertex);float median=points.Select(p=>p.x).OrderBy(v=>v).ElementAt(points.Length/2);for(int i=0;i<points.Length;i++)if(points[i].x<median)editor.Components.Add(i);editor.Frame(view);normals=(Action<Mesh>)typeof(StudioModelEditor).GetMethod("RecalculateEditableNormals",F).CreateDelegate(typeof(Action<Mesh>),editor);changed=(Action<bool>)typeof(StudioModelEditor).GetMethod("PositionsChanged",F).CreateDelegate(typeof(Action<bool>),editor);typeof(StudioModelEditor).GetMethod("PreserveFaceTopology",F).Invoke(editor,null);StudioUndo.IncrementCurrentGroup();report.AppendLine("Body vertices="+points.Length+" selected="+editor.Components.Count+" pipeline="+(UnityEngine.Rendering.GraphicsSettings.currentRenderPipeline?.name??"Built-in"));StudioModelEditor.SceneProfileStage=name=>{long now=Stopwatch.GetTimestamp();if(capturing&&!name.EndsWith(".start"))Add(name,(now-previous)*1000d/Stopwatch.Frequency);previous=now;};deadline=EditorApplication.timeSinceStartup+2;EditorApplication.update+=Tick;}catch(Exception e){Finish(e);}}
 static void Tick(){if(EditorApplication.timeSinceStartup<deadline)return;try{bool capture=sample>=10;capturing=capture;void Save(string key,Stopwatch w){if(capture)Add(key,w.Elapsed.TotalMilliseconds);w.Restart();}var total=Stopwatch.StartNew();var timer=Stopwatch.StartNew();var mesh=editor.ActiveMesh;var selected=editor.SelectedVertices();var points=mesh.vertices;StudioUndo.RegisterCompleteObjectUndo(mesh,"Transform mesh components");foreach(int i in selected)points[i]+=Vector3.up*.00001f;mesh.vertices=points;Save("positions",timer);normals(mesh);Save("normals",timer);mesh.RecalculateBounds();if(mesh.uv.Length==mesh.vertexCount)mesh.RecalculateTangents();EditorUtility.SetDirty(mesh);Save("tangents.bounds",timer);changed(true);Save("changed",timer);view.SendEvent(new Event{type=EventType.Layout,mousePosition=new Vector2(700,400)});Save("layout",timer);view.SendEvent(new Event{type=EventType.Repaint,mousePosition=new Vector2(700,400)});Save("repaint",timer);if(capture)Add("combined",total.Elapsed.TotalMilliseconds);if(++sample>=60)Finish(null);}catch(Exception e){Finish(e);}}
 static void Finish(Exception error){EditorApplication.update-=Tick;SceneView.beforeSceneGui-=BeforeGui;StudioModelEditor.SceneProfileStage=null;if(error!=null)report.AppendLine(error.ToString());foreach(var pair in times){var sorted=pair.Value.OrderBy(x=>x).ToArray();report.AppendLine(pair.Key+" median="+sorted[sorted.Length/2]+" p95="+sorted[(int)Math.Ceiling(sorted.Length*.95)-1]+" max="+sorted.Last());}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../move-viewport-performance.txt")),report.ToString());if(view)view.Close();if(controller)Object.DestroyImmediate(controller);EditorApplication.Exit(error==null?0:1);}
}
